{
    "class": "ADC",
    "schemaVersion": "3.57.0",
    "id": "example-apm-log-setting",
    "tenantA": {
        "class": "Tenant",
        "Shared": {
            "class": "Application",
            "template": "shared",
            "apmService": {
                "class": "Service_HTTP",
                "virtualPort": 8080,
                "virtualAddresses": [
                    "192.0.2.50"
                ],
                "profileAccess": {
                    "use": "accessProfileWithLogSettings"
                }
            },
            "accessProfileWithLogSettings": {
                "class": "Access_Profile",
                "url": "https://apm.example.com/apm/apmProfile.tar.gz",
                "logSettings": [
                    {
                        "use": "apmLogSettingExample"
                    },
                    {
                        "bigip": "/Common/default-log-setting"
                    }
                ],
                "enable": true
            },
            "apmLogSettingExample": {
                "class": "APM_Log_Setting",
                "remark": "Example APM log-setting with urlFilters and access log levels",
                "urlFilters": [
                    {
                        "name": "urlFilterAllowOnly",
                        "filter": {
                            "logAllowedUrl": true,
                            "logBlockedUrl": false
                        },
                        "publisher": {
                            "bigip": "/Common/local-db-publisher"
                        }
                    },
                    {
                        "name": "urlFilterBlockedOnly",
                        "filter": {
                            "logAllowedUrl": false,
                            "logBlockedUrl": true
                        },
                        "publisher": {
                            "bigip": "/Common/local-db-publisher"
                        }
                    }
                ],
                "access": [
                    {
                        "name": "accessLogVerbose",
                        "logLevel": {
                            "accessControl": "debug",
                            "accessPerRequest": "debug",
                            "apmAcl": "info",
                            "eca": "notice",
                            "paa": "warn",
                            "sso": "err",
                            "swg": "crit"
                        },
                        "publisher": {
                            "bigip": "/Common/local-db-publisher"
                        }
                    },
                    {
                        "name": "accessLogOperational",
                        "logLevel": {
                            "accessControl": "info",
                            "accessPerRequest": "notice",
                            "apmAcl": "warn",
                            "eca": "warn",
                            "paa": "warn",
                            "sso": "notice",
                            "swg": "info"
                        },
                        "publisher": {
                            "bigip": "/Common/local-db-publisher"
                        }
                    }
                ]
            }
        }
    }
}
